#[serde(try_from = "Vec<InferenceEvent>", into = "Vec<InferenceEvent>")]
pub struct InferenceEvents(Vec<InferenceEvent>);
impl InferenceEvents { pub fn as_slice(&self) -> &[InferenceEvent] { &self.0 } }
impl TryFrom<Vec<InferenceEvent>> for InferenceEvents {
    type Error = &'static str;
    fn try_from(value: Vec<InferenceEvent>) -> Result<Self, Self::Error> {
        if value.len() <= 64 { Ok(Self(value)) } else { Err("too many InferenceEvents items") }
    }
}
impl From<InferenceEvents> for Vec<InferenceEvent> { fn from(value: InferenceEvents) -> Self { value.0 } }

